onClick:
{{
  Delete_Ligne_Intervention.run()
    .then(() => {
      // 1. On ferme la petite modale de confirmation
      closeModal('modal_delete_ligne_bl');

      // 2. On rafraîchit le tableau pour faire disparaître la ligne
      return Get_Lignes_Intervention.run();
    })
    .then(() => {
      // 3. On met à jour les infos du BL pour recalculer le TOTAL TTC
      return Get_Detail_Intervention.run();
    })
    .then(() => {
      showAlert('Article supprimé avec succès !', 'success');
    })
    .catch((err) => {
      showAlert('Erreur lors de la suppression', 'error');
      console.error(err);
    });
}}
